/// The three independent conversions of the Admission Test: each has its own
/// raw -> scaled table, and its own SAI columns.
enum AtScoreCategory { total, verbal, nonverbal }

/// One row of an SAI table for one category and month bracket: every scaled
/// score from [lo] to [hi] (inclusive) is this [sai]. "ABOVE n" rows use
/// [satOpenHigh] as [hi] and "BELOW n" rows use [satOpenLow] as [lo].
class SaiBand {
  const SaiBand(this.sai, this.lo, this.hi);
  final int sai;
  final int lo;
  final int hi;
}

